CREATE FUNCTION public.location_to_billing_sources(p_location uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb;BEGIN IF auth.uid() IS NULL OR NOT(has_role(auth.uid(),'admin') OR has_role(auth.uid(),'manager')) THEN RAISE EXCEPTION 'Manager access required';END IF;
SELECT jsonb_build_object('orders',COALESCE((SELECT jsonb_agg(to_jsonb(t)) FROM location_task_orders t WHERE location_id=p_location),'[]'::jsonb),'terms',COALESCE((SELECT jsonb_agg(to_jsonb(tm)) FROM location_to_terms tm JOIN location_task_orders t ON t.id=tm.task_order_id WHERE t.location_id=p_location),'[]'::jsonb),'allocations',COALESCE((SELECT jsonb_agg(to_jsonb(a)) FROM location_to_allocations a JOIN location_task_orders t ON t.id=a.task_order_id WHERE t.location_id=p_location),'[]'::jsonb),'stays',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',vp.id,'personnel_id',vp.personnel_id,'in_at',vp.checked_in_at,'out_at',vp.checked_out_at,'signed_at',vp.signed_at,'signature_url',vp.signature_url,'non_billable',p.non_billable,'agency_id',COALESCE(ap.vendor_id,p.vendor_id))) FROM visit_personnel vp JOIN location_visits lv ON lv.id=vp.visit_id JOIN personnel p ON p.id=vp.personnel_id LEFT JOIN personnel_agency_provenance ap ON ap.personnel_id=p.id WHERE lv.location_id=p_location),'[]'::jsonb),'assets',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',a.id,'start_at',a.start_at,'end_at',a.end_at,'type',x.type,'label',x.label,'billable',a.billable)) FROM asset_assignments a JOIN assets x ON x.id=a.asset_id WHERE a.location_id=p_location),'[]'::jsonb),'sheet_entries',COALESCE((SELECT jsonb_agg(to_jsonb(e)||jsonb_build_object('task_order_id',s.task_order_id,'kind',s.kind,'non_billable',p.non_billable)) FROM location_to_sheet_entries e JOIN location_to_sheets s ON s.id=e.sheet_id JOIN location_task_orders t ON t.id=s.task_order_id JOIN personnel p ON p.id=e.personnel_id WHERE t.location_id=p_location AND e.voided_at IS NULL),'[]'::jsonb)) INTO r;RETURN r;END $$;REVOKE ALL ON FUNCTION public.location_to_billing_sources(uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.location_to_billing_sources(uuid) TO authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.location_to_allocations FROM authenticated;REVOKE INSERT ON public.location_to_sheet_entries FROM authenticated;
CREATE FUNCTION public.validate_to_terms_write() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM location_to_allocations WHERE task_order_id=NEW.task_order_id) OR EXISTS(SELECT 1 FROM location_to_sheet_entries e JOIN location_to_sheets s ON s.id=e.sheet_id WHERE s.task_order_id=NEW.task_order_id) THEN RAISE EXCEPTION 'Used TO billing terms are immutable; create a change order';END IF;RETURN NEW;END $$;REVOKE ALL ON FUNCTION public.validate_to_terms_write() FROM PUBLIC,anon,authenticated;CREATE TRIGGER used_to_terms BEFORE UPDATE ON public.location_to_terms FOR EACH ROW EXECUTE FUNCTION public.validate_to_terms_write();